'use strict';
/* ============================================================
   QASR FORGE — procedural Middle Eastern buildings via WFC
   ============================================================ */

/* ---------- seeded RNG (xmur3 + mulberry32) ---------- */
function xmur3(str){ let h=1779033703^str.length; for(let i=0;i<str.length;i++){ h=Math.imul(h^str.charCodeAt(i),3432918353); h=h<<13|h>>>19; } return function(){ h=Math.imul(h^(h>>>16),2246822507); h=Math.imul(h^(h>>>13),3266489909); return (h^=h>>>16)>>>0; }; }
function mulberry32(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; let t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function RNG(seed){ const f=mulberry32(xmur3(String(seed))()); return { f, range:(a,b)=>a+(b-a)*f(), int:(a,b)=>a+Math.floor(f()*(b-a+1)), pick:a=>a[Math.floor(f()*a.length)], chance:p=>f()<p }; }
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const lerp=(a,b,t)=>a+(b-a)*t;

/* ---------- module types ---------- */
const EMPTY=0, ROOM=1, DOME=2, IWAN=3, ARC=4, COURT=5, STAIR=6, TOWER=7, KIOSK=8, GATE=9, BED=10, BATH=11, PRIVY=12;
const NT=13;
// how a module is built: a bedroom or bathroom is a room with its own inner walls and fittings; an outhouse yard is an open court
const BASE_T=t=>t===BED||t===BATH? ROOM : t===PRIVY? COURT : t;
const TINFO=[
  {k:'EMPTY', label:'Open air',      glyph:'·', color:'#8f98a3', desc:'Nothing built. Leaves room for roof terraces, setbacks and light wells.'},
  {k:'ROOM',  label:'Room',          glyph:'R', color:'#c69a5e', desc:'Enclosed room. Each outside face gets windows, doors and dressing from the tradition.'},
  {k:'DOME',  label:'Domed hall',    glyph:'D', color:'#2f9fb2', desc:'Room crowned by a zone of transition, drum and dome. Nothing can stand on it.'},
  {k:'IWAN',  label:'Iwan',          glyph:'I', color:'#4660b0', desc:'Vaulted hall walled on three sides and open on the fourth through one great arch. The open side must face a courtyard or open air.'},
  {k:'ARC',   label:'Arcade',        glyph:'A', color:'#c97c2e', desc:'Piers or columns carrying arches. Shades the rooms behind it; upper arcades become galleries with balustrades.'},
  {k:'COURT', label:'Courtyard',     glyph:'C', color:'#4f9a55', desc:'Open-sky court on the ground. It may never open straight onto the street inside the plot; its outer edges get an enclosure wall.'},
  {k:'STAIR', label:'Stair',         glyph:'S', color:'#7f8693', desc:'Stair core. Stacks only on another stair and finishes in a roof stair-head.'},
  {k:'TOWER', label:'Tower',         glyph:'T', color:'#bf9733', desc:'Minaret, windcatcher or watchtower shaft. Stacks on itself and is capped at the top.'},
  {k:'KIOSK', label:'Roof pavilion', glyph:'K', color:'#bd5878', desc:'Rooftop pavilion standing on a room or arcade: open, glazed or shaded, by tradition.'},
  {k:'GATE',  label:'Gate',          glyph:'G', color:'#ad3b2a', desc:'Entrance vestibule whose portal must face the street.'},
  {k:'BED',   label:'Bedroom',       glyph:'B', color:'#8b6cc0', desc:'Bedroom suite: inner walls split the module into a bedroom and an ensuite, reached through a walk-in wardrobe.'},
  {k:'BATH',  label:'Bathroom',      glyph:'W', color:'#3d8fd1', desc:'Modern fit-out only: a bathroom, a separate WC and a laundry.'},
  {k:'PRIVY', label:'Outhouse',      glyph:'O', color:'#8a7448', desc:'Period fit-out only: a back yard with an outhouse privy, water butt and woodpile. Ground level only.'}
];
const DIRS=[[1,0],[0,1],[-1,0],[0,-1]];
const DIRNAME=['East','South','West','North'];
/* plot grid: nx columns × nz rows (2–4 each) × 4 storeys. cell index i = x + z*nx + l*nc */
const GRID={nx:3,nz:3,nc:9,ncell:36};
function setGrid(nx,nz){ GRID.nx=nx; GRID.nz=nz; GRID.nc=nx*nz; GRID.ncell=nx*nz*4; return GRID; }
const COLN='ABCDE';
const cellName=(x,z)=>COLN[x]+(z+1);
// a tradition's 3×3 plot stretched to another size: edges stay edges, every inner square takes the 3×3 centre row/column
function footFor(st,nx,nz){ const m=(i,n)=>i===0?0:i===n-1?2:1, o=[]; for(let z=0;z<nz;z++) for(let x=0;x<nx;x++) o.push(st.foot[m(x,nx)+m(z,nz)*3]); return o; }

