for(const s of STYLES){ const n=SUITE_NAMES[s.id]||['Bedroom suite','Bathroom','Privy'], r=!!s.ruin;
  s.names.BED=s.names.BED||n[0]; s.names.BATH=s.names.BATH||n[1]; s.names.PRIVY=s.names.PRIVY||n[2];
  // ruins have no fittings left; elsewhere bedrooms are common, a bathroom or an outhouse is one module among many
  if(s.w.BED==null) s.w.BED= r? 0 : Math.round(s.w.ROOM*4.5)/10; if(s.w.BATH==null) s.w.BATH= r? 0 : 0.8; if(s.w.PRIVY==null) s.w.PRIVY= r? 0 : 0.7; }
