function tLabel(t,st){ st=st||(typeof S!=='undefined'&&STYLE[S.styleId]); const k=TINFO[t].k, m=!st? null : st.tlabel? st.tlabel : st.region!=='asia'? null : st.id==='haveli'? TLABEL_HAVELI : TLABEL_ASIA; return (m&&m[k])||TINFO[t].label; }

