function roomName(st,ty,l,x,z){
  const key=TINFO[ty].k; const n=st.names[key];
  if(n==null) return TINFO[ty].label;
  if(typeof n==='string') return n;
  if(ty===TOWER) return l===0? n[0] : n[1];
  // ROOM: per-level lists or [ground, upper]
  let list = n.length>=4 ? n[Math.min(l,n.length-1)] : (l===0? n[0] : n[1]);
  return list[(x*7+z*3+l*5)%list.length];
}
